        if (left == 0)
                return SC_ERROR_INVALID_ASN1_OBJECT;
        len = *p;
        p++;
        left--;
        if (len & 0x80) {
                len &= 0x7f;
                unsigned int a = 0;
                if (len > sizeof a || len > left)
                        return SC_ERROR_INVALID_ASN1_OBJECT;
                for (i = 0; i < len; i++) {
                        a <<= 8;
                        a |= *p;
                        p++;
                        left--;
                }
                len = a;
        }

        *cla_out = cla;
        *tag_out = tag;
        *taglen = len;
        *buf = p;

        if (len > left)
                return SC_ERROR_ASN1_END_OF_CONTENTS;

        return SC_SUCCESS;
